-- ============================================================
-- Update all pipeline email templates:
--   1. White header background (logo + title on white, coloured accent bar)
--   2. Add French (subject_fr + body_html_fr) to every template
-- ============================================================

-- ─── HELPER: reusable header style ───────────────────────────
-- Each template gets:
--   • white card background
--   • coloured top accent bar (4px)
--   • logo centred on white
--   • headline in brand colour
-- ─────────────────────────────────────────────────────────────


-- ══════════════════════════════════════════════════════════════
-- 1. ONBOARDING
-- ══════════════════════════════════════════════════════════════
UPDATE sales_pipeline_email_templates SET
  body_html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Onboarding</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#0ea5e9;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#0ea5e9;font-size:26px;font-weight:700;letter-spacing:-0.5px;">Welcome aboard, {{contact.first_name}}!</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">Your onboarding journey begins today</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">We''re thrilled to have <strong>{{org.name}}</strong> join the Aliice family. Your account is now in the <strong>Onboarding</strong> phase and we''re here every step of the way.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;"><tr><td style="background:#f0f9ff;border-left:4px solid #0ea5e9;border-radius:8px;padding:16px 20px;"><p style="margin:0;font-size:14px;font-weight:700;color:#0284c7;">Step 1 — Set up your clinic profile</p><p style="margin:6px 0 0;font-size:14px;color:#475569;">Add your logo, services, team members and working hours.</p></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;"><tr><td style="background:#f0fdf4;border-left:4px solid #22c55e;border-radius:8px;padding:16px 20px;"><p style="margin:0;font-size:14px;font-weight:700;color:#16a34a;">Step 2 — Invite your team</p><p style="margin:6px 0 0;font-size:14px;color:#475569;">Add staff accounts so everyone can collaborate.</p></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 28px;"><tr><td style="background:#fdf4ff;border-left:4px solid #a855f7;border-radius:8px;padding:16px 20px;"><p style="margin:0;font-size:14px;font-weight:700;color:#9333ea;">Step 3 — Book your onboarding call</p><p style="margin:6px 0 0;font-size:14px;color:#475569;">Our team will walk you through every feature live.</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">Your dedicated success manager will reach out within <strong>24 hours</strong>. In the meantime, feel free to explore the platform.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#0ea5e9;border-radius:10px;"><a href="https://www.aliice.app/{{org.slug}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Go to my dashboard →</a></td></tr></table></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;">Questions? <a href="mailto:hello@aliice.app" style="color:#0ea5e9;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · All-in-one clinic management platform</p></td></tr></table></td></tr></table></body></html>',

  subject_fr = 'Votre parcours d''intégration Aliice commence maintenant, {{org.name}} 🚀',

  body_html_fr = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Intégration</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#0ea5e9;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#0ea5e9;font-size:26px;font-weight:700;">Bienvenue, {{contact.first_name}} !</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">Votre parcours d''intégration commence aujourd''hui</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">Nous sommes ravis d''accueillir <strong>{{org.name}}</strong> dans la famille Aliice. Votre compte est maintenant en phase d''<strong>intégration</strong> et nous vous accompagnons à chaque étape.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;"><tr><td style="background:#f0f9ff;border-left:4px solid #0ea5e9;border-radius:8px;padding:16px 20px;"><p style="margin:0;font-size:14px;font-weight:700;color:#0284c7;">Étape 1 — Configurez votre profil clinique</p><p style="margin:6px 0 0;font-size:14px;color:#475569;">Ajoutez votre logo, vos services, votre équipe et vos horaires.</p></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;"><tr><td style="background:#f0fdf4;border-left:4px solid #22c55e;border-radius:8px;padding:16px 20px;"><p style="margin:0;font-size:14px;font-weight:700;color:#16a34a;">Étape 2 — Invitez votre équipe</p><p style="margin:6px 0 0;font-size:14px;color:#475569;">Ajoutez des comptes collaborateurs pour travailler ensemble.</p></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 28px;"><tr><td style="background:#fdf4ff;border-left:4px solid #a855f7;border-radius:8px;padding:16px 20px;"><p style="margin:0;font-size:14px;font-weight:700;color:#9333ea;">Étape 3 — Planifiez votre appel d''intégration</p><p style="margin:6px 0 0;font-size:14px;color:#475569;">Notre équipe vous guidera à travers toutes les fonctionnalités en direct.</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">Votre responsable de succès dédié vous contactera dans les <strong>24 heures</strong>. En attendant, n''hésitez pas à explorer la plateforme.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#0ea5e9;border-radius:10px;"><a href="https://www.aliice.app/{{org.slug}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Accéder à mon tableau de bord →</a></td></tr></table></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;">Des questions ? <a href="mailto:hello@aliice.app" style="color:#0ea5e9;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · Plateforme tout-en-un pour cliniques</p></td></tr></table></td></tr></table></body></html>'

WHERE name = 'Onboarding – Welcome to Your Journey';


