-- 2. CONTACTED
-- ══════════════════════════════════════════════════════════════
UPDATE sales_pipeline_email_templates SET
  body_html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Follow-up</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#6366f1;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#6366f1;font-size:26px;font-weight:700;">Hi {{contact.first_name}}, quick hello 👋</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">We noticed your interest in Aliice</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">We saw that <strong>{{org.name}}</strong> has been exploring Aliice and we''d love the chance to show you how we help clinics like yours save time and grow.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 28px;"><tr><td width="48%" style="background:#f0f9ff;border-radius:12px;padding:20px;vertical-align:top;"><p style="margin:0 0 8px;font-size:22px;">⚡</p><p style="margin:0 0 6px;font-size:14px;font-weight:700;color:#0f172a;">Save hours every week</p><p style="margin:0;font-size:13px;color:#64748b;line-height:1.6;">Automate appointments, invoices, and patient communications.</p></td><td width="4%"></td><td width="48%" style="background:#fdf4ff;border-radius:12px;padding:20px;vertical-align:top;"><p style="margin:0 0 8px;font-size:22px;">📈</p><p style="margin:0 0 6px;font-size:14px;font-weight:700;color:#0f172a;">Grow your practice</p><p style="margin:0;font-size:13px;color:#64748b;line-height:1.6;">Built-in CRM, pipeline tracking, and marketing tools.</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">Would you have <strong>20 minutes</strong> for a quick call this week? We''ll show you what Aliice can do for <strong>{{org.name}}</strong> specifically — no sales pitch, just a real demo.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#6366f1;border-radius:10px;"><a href="https://www.aliice.app/demo" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Book a free demo →</a></td></tr></table><p style="margin:24px 0 0;font-size:14px;color:#64748b;text-align:center;">Or simply reply to this email — we read every message.</p></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#6366f1;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · All-in-one clinic management platform</p></td></tr></table></td></tr></table></body></html>',

  subject_fr = 'Prenons le temps d''échanger, {{contact.first_name}} 👋',

  body_html_fr = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Suivi</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#6366f1;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#6366f1;font-size:26px;font-weight:700;">Bonjour {{contact.first_name}} 👋</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">Nous avons remarqué votre intérêt pour Aliice</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">Nous avons vu que <strong>{{org.name}}</strong> explore Aliice et nous serions ravis de vous montrer comment nous aidons des cliniques comme la vôtre à gagner du temps et à se développer.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 28px;"><tr><td width="48%" style="background:#f0f9ff;border-radius:12px;padding:20px;vertical-align:top;"><p style="margin:0 0 8px;font-size:22px;">⚡</p><p style="margin:0 0 6px;font-size:14px;font-weight:700;color:#0f172a;">Gagnez des heures chaque semaine</p><p style="margin:0;font-size:13px;color:#64748b;line-height:1.6;">Automatisez rendez-vous, factures et communications patients.</p></td><td width="4%"></td><td width="48%" style="background:#fdf4ff;border-radius:12px;padding:20px;vertical-align:top;"><p style="margin:0 0 8px;font-size:22px;">📈</p><p style="margin:0 0 6px;font-size:14px;font-weight:700;color:#0f172a;">Développez votre pratique</p><p style="margin:0;font-size:13px;color:#64748b;line-height:1.6;">CRM intégré, suivi pipeline et outils marketing.</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">Auriez-vous <strong>20 minutes</strong> cette semaine pour un appel rapide ? Nous vous montrerons ce qu''Aliice peut faire pour <strong>{{org.name}}</strong> — sans argumentaire commercial, juste une vraie démo.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#6366f1;border-radius:10px;"><a href="https://www.aliice.app/demo" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Réserver une démo gratuite →</a></td></tr></table><p style="margin:24px 0 0;font-size:14px;color:#64748b;text-align:center;">Ou répondez simplement à cet e-mail — nous lisons chaque message.</p></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#6366f1;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · Plateforme tout-en-un pour cliniques</p></td></tr></table></td></tr></table></body></html>'

WHERE name = 'Follow-up – We''d Love to Connect';


