-- 3. CHURNED / WIN-BACK
-- ══════════════════════════════════════════════════════════════
UPDATE sales_pipeline_email_templates SET
  body_html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Win-back</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#f97316;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#f97316;font-size:26px;font-weight:700;">We miss you, {{contact.first_name}} 💛</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">A lot has changed since you left</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">We noticed <strong>{{org.name}}</strong> hasn''t been active lately and we wanted to reach out personally. We''ve shipped a lot of improvements you asked for — and we think you''ll love what''s new.</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#fff7ed;border-radius:12px;padding:24px;margin:0 0 28px;"><tr><td><p style="margin:0 0 14px;font-size:15px;font-weight:700;color:#9a3412;">What''s new in Aliice 🚀</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #fed7aa;padding-bottom:10px;">✅ <strong>New booking flow</strong> — faster, mobile-friendly patient scheduling</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #fed7aa;padding-bottom:10px;">✅ <strong>Integrated payments</strong> — invoicing with Payrexx, right inside Aliice</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #fed7aa;padding-bottom:10px;">✅ <strong>Two-way Gmail sync</strong> — manage all client emails without leaving the app</p><p style="margin:0;font-size:14px;color:#334155;">✅ <strong>Team calendar</strong> — Google Meet meetings, straight from Aliice</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">We''d love to welcome <strong>{{org.name}}</strong> back. If there was something that didn''t work for you before, tell us — we read every reply.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#f97316;border-radius:10px;"><a href="https://www.aliice.app/{{org.slug}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Reactivate my account →</a></td></tr></table><p style="margin:24px 0 0;font-size:13px;color:#94a3b8;text-align:center;">Not ready yet? No worries — we''ll keep the door open.</p></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#f97316;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · All-in-one clinic management platform</p></td></tr></table></td></tr></table></body></html>',

  subject_fr = 'Vous nous manquez — voici les nouveautés d''Aliice ✨',

  body_html_fr = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Win-back</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#f97316;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#f97316;font-size:26px;font-weight:700;">Vous nous manquez, {{contact.first_name}} 💛</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">Beaucoup de choses ont changé depuis votre départ</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">Nous avons remarqué que <strong>{{org.name}}</strong> n''était plus actif dernièrement et nous tenions à vous contacter personnellement. Nous avons ajouté de nombreuses améliorations — et nous pensons que vous allez adorer.</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#fff7ed;border-radius:12px;padding:24px;margin:0 0 28px;"><tr><td><p style="margin:0 0 14px;font-size:15px;font-weight:700;color:#9a3412;">Les nouveautés d''Aliice 🚀</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #fed7aa;padding-bottom:10px;">✅ <strong>Nouveau flux de réservation</strong> — prise de RDV rapide et mobile</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #fed7aa;padding-bottom:10px;">✅ <strong>Paiements intégrés</strong> — facturation avec Payrexx, directement dans Aliice</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #fed7aa;padding-bottom:10px;">✅ <strong>Synchronisation Gmail bidirectionnelle</strong> — gérez tous vos e-mails clients sans quitter l''app</p><p style="margin:0;font-size:14px;color:#334155;">✅ <strong>Calendrier d''équipe</strong> — réunions Google Meet, directement depuis Aliice</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">Nous serions ravis de revoir <strong>{{org.name}}</strong>. Si quelque chose ne fonctionnait pas avant, dites-le nous — nous lisons chaque réponse.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#f97316;border-radius:10px;"><a href="https://www.aliice.app/{{org.slug}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Réactiver mon compte →</a></td></tr></table><p style="margin:24px 0 0;font-size:13px;color:#94a3b8;text-align:center;">Pas encore prêt ? Pas de souci — la porte reste ouverte.</p></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#f97316;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · Plateforme tout-en-un pour cliniques</p></td></tr></table></td></tr></table></body></html>'

WHERE name = 'Win-back – We Miss You, {{org.name}}';


