  body_html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Welcome – Active Client</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#0ea5e9;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#0ea5e9;font-size:26px;font-weight:700;">Welcome to Aliice, {{contact.first_name}}! 🎉</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">{{org.name}} is now an active Aliice client</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">Congratulations — <strong>{{org.name}}</strong> is now fully activated on Aliice. Your team has everything it needs to deliver an exceptional patient experience.</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#f0f9ff;border-radius:12px;padding:24px;margin:0 0 28px;"><tr><td><p style="margin:0 0 12px;font-size:15px;font-weight:700;color:#0284c7;">Your Aliice plan includes:</p><p style="margin:0 0 8px;font-size:14px;color:#334155;">✅ Unlimited patient records &amp; appointments</p><p style="margin:0 0 8px;font-size:14px;color:#334155;">✅ Automated invoicing &amp; online payments</p><p style="margin:0 0 8px;font-size:14px;color:#334155;">✅ Two-way Gmail &amp; Google Calendar integration</p><p style="margin:0;font-size:14px;color:#334155;">✅ Dedicated support from your success manager</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">Log in any time and reach out to us whenever you need — we''re here to make sure you succeed.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#0ea5e9;border-radius:10px;"><a href="https://www.aliice.app/{{org.slug}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Go to my dashboard →</a></td></tr></table></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#0ea5e9;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · All-in-one clinic management platform</p></td></tr></table></td></tr></table></body></html>',

  subject_fr = 'Bienvenue sur Aliice, {{contact.first_name}} ! 🎉',

  body_html_fr = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Bienvenue – Client actif</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#0ea5e9;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;" /><h1 style="margin:0;color:#0ea5e9;font-size:26px;font-weight:700;">Bienvenue sur Aliice, {{contact.first_name}} ! 🎉</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">{{org.name}} est maintenant un client Aliice actif</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 20px;color:#334155;font-size:16px;line-height:1.7;">Félicitations — <strong>{{org.name}}</strong> est maintenant entièrement activé sur Aliice. Votre équipe dispose de tout ce dont elle a besoin pour offrir une expérience patient exceptionnelle.</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#f0f9ff;border-radius:12px;padding:24px;margin:0 0 28px;"><tr><td><p style="margin:0 0 12px;font-size:15px;font-weight:700;color:#0284c7;">Votre abonnement Aliice inclut :</p><p style="margin:0 0 8px;font-size:14px;color:#334155;">✅ Dossiers patients &amp; rendez-vous illimités</p><p style="margin:0 0 8px;font-size:14px;color:#334155;">✅ Facturation automatisée &amp; paiements en ligne</p><p style="margin:0 0 8px;font-size:14px;color:#334155;">✅ Intégration Gmail &amp; Google Agenda bidirectionnelle</p><p style="margin:0;font-size:14px;color:#334155;">✅ Support dédié de votre responsable de succès</p></td></tr></table><p style="margin:0 0 28px;color:#334155;font-size:15px;line-height:1.7;">Connectez-vous à tout moment et contactez-nous dès que vous en avez besoin — nous sommes là pour vous aider à réussir.</p><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="background:#0ea5e9;border-radius:10px;"><a href="https://www.aliice.app/{{org.slug}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Accéder à mon tableau de bord →</a></td></tr></table></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#0ea5e9;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · Plateforme tout-en-un pour cliniques</p></td></tr></table></td></tr></table></body></html>'

WHERE id IN (
  SELECT template_id FROM sales_pipeline_automations
  WHERE trigger_stage = 'active' AND active = true AND template_id IS NOT NULL
  LIMIT 1
);


